        --color-text: #172033;
        --color-muted: #56647a;
        --color-border: #c9d3e2;
        --color-primary: #2457d6;
        --color-primary-hover: #1b44ad;
        --color-focus: #7c3aed;
        --color-error: #b42318;
        --shadow-card: 0 24px 60px #d7deeb;
        --radius-lg: 24px;
        --radius-md: 14px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 320px;
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--color-text);
        background:
          radial-gradient(circle at top left, #e4edff 0, transparent 34rem),
          var(--color-bg);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 1;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: var(--color-surface);
        background: var(--color-primary);
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-focus);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      main {
        width: min(100%, 34rem);
      }

      .card {
        overflow-wrap: anywhere;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        padding: clamp(1.25rem, 5vw, 2.5rem);
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--color-primary);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3rem);
        line-height: 1.08;
        letter-spacing: -0.04em;
      }

      .intro {
        margin: 1rem 0 0;
        color: var(--color-muted);
        font-size: 1.0625rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
        margin-top: 2rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.85rem;
        align-items: start;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-md);
        padding: 1rem;
        background: #fbfdff;
      }

      .form-field:focus-within {
        border-color: var(--color-primary);
        box-shadow: 0 0 0 4px #dfe7ff;
      }

      input[type="checkbox"] {
        width: 1.35rem;
        height: 1.35rem;
        margin: 0.15rem 0 0;
        accent-color: var(--color-primary);
      }

      input[type="checkbox"]:focus-visible,
      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-focus);
      }

      label {
        display: block;
        font-weight: 700;
      }

      .required {
        font-weight: 700;
      }

      .helper-text {
        margin: 0.3rem 0 0;
        color: var(--color-muted);
        font-size: 0.95rem;
      }

      .error-message {
        display: none;
        grid-column: 2;
        margin: 0;
        color: var(--color-error);
        font-weight: 700;
      }

      .form-field.is-invalid {
        border-color: var(--color-error);
      }

      .form-field.is-invalid .error-message {
        display: block;
      }

      button {
        min-height: 3rem;
        border: 0;
        border-radius: 999px;
        padding: 0.85rem 1.25rem;
        color: var(--color-surface);
        background: var(--color-primary);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        background: var(--color-primary-hover);
      }

      button:active {
        transform: translateY(1px);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: var(--color-primary-hover);
        font-weight: 700;
      }

      @media (max-width: 25rem) {
        .form-field {
          grid-template-columns: 1fr;
        }

        .error-message {
          grid-column: 1;
        }
      }

      @media (forced-colors: active) {
        .card,
